# Prebuilt `agentastic` binary from the //core/agent Rust workspace, installed as `agentastic`,
# alongside the `agentastic-code-mode-host` helper it spawns for Code Mode. Release train: stable.
class Agentastic < Formula
  desc "Agentastic coding agent CLI"
  homepage "https://www.agentastic.dev"
  version "0.21.0"
  license "Apache-2.0"

  BASE = "https://releases.agentastic.ai/agent/v0.21.0".freeze

  # Homebrew loads every declared conflict, even when it is not installed. Only
  # inspect active kegs so upgrading one trusted train does not require trusting
  # the other trains (or loading a nightly formula that has not been published).
  ["agentastic-beta", "agentastic-nightly"].each do |name|
    next unless (HOMEBREW_PREFIX/"var/homebrew/linked"/name).exist? && (HOMEBREW_PREFIX/"opt"/name).exist?

    conflicts_with "agentasticai/tap/#{name}",
      because: "every Agentastic release train installs the `agentastic` command"
  end

  on_macos do
    on_arm do
      url "#{BASE}/agentastic-0.21.0-aarch64-apple-darwin.tar.gz"
      sha256 "9863eff52cf2dab28f4059db0590e15b00a4c0acc462ae7c4bf8d2676c93757b"
    end
    on_intel do
      url "#{BASE}/agentastic-0.21.0-x86_64-apple-darwin.tar.gz"
      sha256 "4ba9fc109f02f43d21baad4b28584b38dbfb27576b77b407f95bc9ade0781c1b"
    end
  end

  on_linux do
    on_arm do
      url "#{BASE}/agentastic-0.21.0-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "bf25b7a7103f200c04758def3596485657f39b6b61ca447e9bd4d3bef9956d64"
    end
    on_intel do
      url "#{BASE}/agentastic-0.21.0-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "8adf3651a587758aaf5be50dd90e21e5ed17df3e24583b9db0148376a3f82be8"
    end
  end

  def install
    # Tarball holds two stripped binaries: the CLI and the code-mode host, which the
    # CLI spawns from its own bin dir under that exact name. The background daemon
    # installs its app server only from a complete package (both binaries plus this
    # metadata), so keep them together in libexec, apart from the keg's receipts.
    # `channel` is the train `agentastic` keeps upgrading along.
    (libexec/"bin").install "agentastic", "agentastic-code-mode-host"
    triple = "#{Hardware::CPU.arm? ? "aarch64" : "x86_64"}-#{OS.mac? ? "apple-darwin" : "unknown-linux-gnu"}"
    (libexec/"agentastic-package.json").write <<~JSON
      {"layoutVersion":1,"version":"#{version}","target":"#{triple}","variant":"agentastic","entrypoint":"bin/agentastic","resourcesDir":"agentastic-resources","pathDir":"agentastic-path","channel":"stable"}
    JSON
    bin.install_symlink libexec/"bin/agentastic" => "agentastic"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/agentastic --version")
  end
end
